const IMG = "?auto=format&fit=crop&w=1200&q=82";
const cases = [
  {id:1,cat:"Image Verification",icon:"AI",title:"Did the Pope really wear a luxury puffer jacket?",note:"Trace a viral AI image to its origin",verdict:"Potentially misleading",level:"Intermediate",time:12,image:"https://images.unsplash.com/photo-1515542622106-78bda8ba0e5b"+IMG,publisher:"Viral social post",published:"AI image case · 2023",deck:"A polished image appears to show Pope Francis wearing an oversized white designer jacket.",body:["The image spread widely with captions treating it as a candid photograph.","No photographer, agency credit, location, or original publication accompanied the earliest reposts.","A source hunt leads to an AI creator rather than a news photographer."],prompt:"Can you locate the earliest upload and a credible report explaining its origin?",hint:"Reverse-search the image and inspect whether the earliest account identifies itself as an AI creator.",source:"https://apnews.com/article/9805fec11681adbf88d3a7c73bdf47de"},
  {id:2,cat:"Image Verification",icon:"EX",title:"Was there an explosion beside the Pentagon?",note:"Verify a breaking-news image before markets react",verdict:"Potentially misleading",level:"Advanced",time:14,image:"https://images.unsplash.com/photo-1529107386315-e1a2ed48a620"+IMG,publisher:"Unverified breaking-news account",published:"AI image case · 2023",deck:"A smoky image claims to show an explosion near the Pentagon and rapidly circulates as breaking news.",body:["The post cites no emergency agency or on-scene reporter.","Local officials report no incident while the image contains warped architectural details.","Several accounts repeat the same claim without adding independent evidence."],prompt:"Which official local sources could confirm an explosion within minutes?",hint:"Check fire, police, defense, and reputable local news channels before analyzing pixels.",source:"https://apnews.com/article/5e344fc9134741d4f5dc17ed04262940"},
  {id:3,cat:"Technology",icon:"VO",title:"A president calls and tells voters to stay home",note:"Detect voice cloning and caller-ID spoofing",verdict:"Potentially misleading",level:"Advanced",time:15,image:"https://images.unsplash.com/photo-1478737270239-2f02b77fc618"+IMG,publisher:"Automated phone call",published:"Voice-cloning case · 2024",deck:"Voters receive a call that sounds like a national leader telling them not to vote in a primary.",body:["A familiar-sounding voice is not proof of identity.","The caller ID appears connected to a political figure, but phone numbers can be spoofed.","The FCC later documented the AI-generated message and enforcement action."],prompt:"What channel can independently confirm whether the speaker made this announcement?",hint:"Find the official campaign statement and the election authority's public notice.",source:"https://docs.fcc.gov/public/attachments/FCC-24-17A3.pdf"},
  {id:4,cat:"Technology",icon:"DF",title:"Did Zelenskyy tell Ukrainian troops to surrender?",note:"Inspect a political deepfake and its context",verdict:"Potentially misleading",level:"Advanced",time:15,image:"https://images.unsplash.com/photo-1485846234645-a62644f84728"+IMG,publisher:"Reposted video clip",published:"Deepfake case · 2022",deck:"A low-resolution video appears to show Ukraine's president ordering troops to lay down their arms.",body:["The head and neck move unnaturally and the voice quality differs from verified addresses.","The clip appears without a full broadcast or authentic newsroom archive.","Verified statements from the same day contradict the surrender message."],prompt:"How would you compare this clip with a verified address from the same day?",hint:"Compare facial motion, voice cadence, background, and the leader's official channels.",source:"https://www.marketscreener.com/news/latest/Deepfake-footage-purports-to-show-Ukrainian-president-capitulating-39784454/"},
  {id:5,cat:"Image Verification",icon:"FR",title:"Is the Eiffel Tower on fire?",note:"Separate spectacular visuals from verified events",verdict:"Potentially misleading",level:"Intermediate",time:11,image:"https://images.unsplash.com/photo-1502602898657-3e91760cbb34"+IMG,publisher:"Short-video account",published:"Synthetic-media case · 2024",deck:"Dramatic night footage shows flames apparently engulfing the Eiffel Tower.",body:["The uploader provides no date, location verification, or emergency-service source.","No matching alert appears on official city or monument channels.","Reverse-searching frames reveals manipulated or synthetic versions."],prompt:"What real-world evidence should exist if a landmark fire of this scale happened?",hint:"Look for fire-service alerts, official monument updates, and multiple independent angles.",source:"https://fullfact.org/online/photos-eiffel-tower-fire-false/"},
  {id:6,cat:"Image Verification",icon:"SH",title:"A shark swims down a flooded highway",note:"Unmask a recycled Photoshop classic",verdict:"Potentially misleading",level:"Beginner",time:10,image:"https://images.unsplash.com/photo-1560275619-4662e36fa65c"+IMG,publisher:"Storm update account",published:"Recycled image case",deck:"After a hurricane, a familiar photo claims to show a shark swimming beside cars on a flooded highway.",body:["The same composite has resurfaced after several unrelated storms.","The shark and highway portions trace to different original photographs.","A reverse-image timeline is more useful here than visual intuition alone."],prompt:"Can you find an older appearance that predates the current storm?",hint:"Use reverse image search and set the date range to before the storm.",source:"https://africacheck.org/fact-checks/meta-programme-fact-checks/shark-swimming-flooded-highway-no-image-photoshopped"},
  {id:7,cat:"Technology",icon:"GM",title:"Is this real footage from a current war?",note:"Recognize video-game clips presented as combat",verdict:"Potentially misleading",level:"Intermediate",time:13,image:"https://images.unsplash.com/photo-1542751371-adc38448a05e"+IMG,publisher:"Anonymous conflict account",published:"Game-footage case",deck:"A grainy night clip is described as a live missile interception from a current conflict.",body:["The clip is filmed off a screen and has no location, date, or original camera source.","Interface fragments and unnatural particle effects resemble the game Arma 3.","The game's developer has documented repeated misuse of gameplay as news footage."],prompt:"Which visual and source clues distinguish a simulation from field footage?",hint:"Look for HUD elements, unnatural smoke, missing sound, and the earliest upload.",source:"https://www.bohemia.net/en/blog/arma-3-footage-being-used-as-fake-news%20/"},
  {id:8,cat:"Health & Science",icon:"GA",title:"Can eating garlic prevent COVID-19?",note:"Check a health remedy against medical evidence",verdict:"Potentially misleading",level:"Beginner",time:10,image:"https://images.unsplash.com/photo-1540148426945-6cf22a6b2383"+IMG,publisher:"Wellness group post",published:"Health myth",deck:"A post says a common kitchen ingredient can prevent infection and replaces proven precautions.",body:["Garlic is a food with some antimicrobial properties, but that does not establish protection from a specific virus.","The post provides no clinical trial or public-health guidance.","WHO states there is no evidence that eating garlic protected people from COVID-19."],prompt:"What kind of evidence would be needed for a prevention claim?",hint:"Search a public-health authority and distinguish laboratory properties from clinical outcomes.",source:"https://www.who.int/news-room/questions-and-answers/item/coronavirus-disease-covid-19-food-safety-and-nutrition"},
  {id:9,cat:"Health & Science",icon:"UV",title:"Should UV lamps be used to disinfect skin?",note:"Identify dangerous advice hidden in a viral tip",verdict:"Potentially misleading",level:"Intermediate",time:11,image:"https://images.unsplash.com/photo-1584634731339-252c581abfc5"+IMG,publisher:"Forwarded health message",published:"Safety myth",deck:"A viral checklist recommends using ultraviolet lamps directly on hands and skin to kill a virus.",body:["The post borrows scientific language but gives no dose, device, or safety standard.","UV exposure can damage skin and eyes.","Authoritative guidance warns against using UV lamps on the body."],prompt:"Does the source discuss both effectiveness and harm?",hint:"Safety advice needs an identifiable health authority, not only a mechanism claim.",source:"https://www.who.int/vietnam/emergencies/covid-19-in-vietnam/information/mythbusters"},
  {id:10,cat:"Climate",icon:"CL",title:"A cold week proves global warming stopped",note:"Separate short-term weather from long-term climate",verdict:"Potentially misleading",level:"Intermediate",time:12,image:"https://images.unsplash.com/photo-1483664852095-d6cc6870702d"+IMG,publisher:"Viral weather post",published:"Climate context case",deck:"A post uses one local cold spell as proof that global warming is not happening.",body:["Weather describes short-term local conditions; climate uses long-term patterns, commonly over 30 years.","A local cold extreme can occur in a warming global climate.","The claim changes scale—from one place and week to the entire planet and decades."],prompt:"Are the time period and geographic scale appropriate for the conclusion?",hint:"Compare the post's one-week observation with a long-term global dataset.",source:"https://www.noaa.gov/explainers/what-s-difference-between-climate-and-weather"},
  {id:11,cat:"Public Policy",icon:"FE",title:"FEMA will take your land if you apply for aid",note:"Verify a disaster rumor against program rules",verdict:"Potentially misleading",level:"Intermediate",time:12,image:"https://images.unsplash.com/photo-1547683905-f686c993aae5"+IMG,publisher:"Neighborhood group message",published:"Disaster rumor · 2024",deck:"A widely shared message warns disaster survivors that applying for assistance transfers ownership of their property.",body:["The warning provides no application clause, policy document, or named official.","Fear may stop eligible survivors from requesting urgent help.","FEMA states that applying does not grant the government ownership of property or land."],prompt:"Where should a survivor verify eligibility and legal conditions?",hint:"Use the agency's official rumor-control page, not a screenshot of a forwarded message.",source:"https://www.fema.gov/print/pdf/node/686154"},
  {id:12,cat:"Scams",icon:"PK",title:"Pay a small fee to redeliver your package",note:"Spot an impersonation link in a text message",verdict:"Potentially misleading",level:"Beginner",time:10,image:"https://images.unsplash.com/photo-1586769852836-bc069f19e1b6"+IMG,publisher:"Unexpected SMS",published:"Delivery scam",deck:"A text using a postal-service name says your package is held and requests card details for redelivery.",body:["The message arrives unexpectedly and uses urgency to push a link.","The web address does not match the official postal domain.","The FTC warns that real USPS messages do not demand payment to redeliver an unexpected package."],prompt:"How can you check the shipment without using the message's link?",hint:"Open the carrier's official app or type its known website yourself.",source:"https://consumer.ftc.gov/consumer-alerts/2022/08/dont-click-random-text-its-scam"},
  {id:13,cat:"Scams",icon:"SC",title:"You are a scholarship finalist—pay to claim it",note:"Detect pressure and upfront-fee scholarship scams",verdict:"Potentially misleading",level:"Beginner",time:11,image:"https://images.unsplash.com/photo-1523050854058-8df90110c9f1"+IMG,publisher:"Unsolicited award email",published:"Student scam",deck:"An email says you are a finalist for a scholarship you never entered and asks for a processing fee.",body:["The offer guarantees funding and says the opportunity expires today.","It asks for a fee before providing verifiable award rules.","Legitimate scholarships do not require payment to apply or release an award."],prompt:"Can the award be verified through a school adviser or official sponsor website?",hint:"Search the sponsor independently and never use the payment link in the message.",source:"https://consumer.ftc.gov/articles/how-avoid-scholarship-and-financial-aid-scams"},
  {id:14,cat:"Scams",icon:"SL",title:"A limited-time student loan forgiveness agent",note:"Check official seals, fees, and special-access claims",verdict:"Potentially misleading",level:"Intermediate",time:13,image:"https://images.unsplash.com/photo-1554224155-8d04cb21cd6c"+IMG,publisher:"Loan relief caller",published:"Impersonation scam",deck:"A caller with an official-looking logo promises immediate loan forgiveness if you pay and share your FSA ID.",body:["Government seals and knowledge of your loan balance do not prove affiliation.","The caller creates urgency and promises special access to a program.","Official guidance says help is free at StudentAid.gov and an FSA ID must not be shared."],prompt:"Which official account should you use to check eligibility?",hint:"End the call and sign in through a web address you already know.",source:"https://consumer.ftc.gov/consumer-alerts/2024/04/scammers-follow-news-about-student-loan-forgiveness"},
  {id:15,cat:"Scams",icon:"JB",title:"A recruiter hires you before an interview",note:"Verify a remote job before sharing bank details",verdict:"Potentially misleading",level:"Intermediate",time:12,image:"https://images.unsplash.com/photo-1521737604893-d14cc237f11d"+IMG,publisher:"Personal email account",published:"Job scam",deck:"A recruiter for a famous company offers a remote role immediately and asks for direct-deposit details.",body:["The sender uses a personal email address rather than the employer's domain.","They request financial information before a real interview.","The FTC recommends contacting the company through a known official channel."],prompt:"Can the recruiter and vacancy be found on the employer's official site?",hint:"Search the recruiter's name plus “scam” and call the employer using a verified number.",source:"https://consumer.ftc.gov/consumer-alerts/2025/07/job-scammers-are-looking-hire-you"},
  {id:16,cat:"Campus",icon:"PR",title:"A professor offers a paid assistant job by email",note:"Recognize a fake-check scam targeting students",verdict:"Potentially misleading",level:"Intermediate",time:14,image:"https://images.unsplash.com/photo-1523240795612-9a054b0db644"+IMG,publisher:"Spoofed campus email",published:"Campus scam",deck:"An email appearing to come from a professor offers easy work, mails a check, and asks you to forward part of the money.",body:["A familiar name or campus-style address can be spoofed or compromised.","Banks may make funds available before discovering a check is fake.","Sending part of the funds leaves the student responsible when the check bounces."],prompt:"How could you verify the professor and job without replying?",hint:"Contact the professor or career office through the university directory.",source:"https://consumer.ftc.gov/consumer-alerts/2024/04/college-students-are-targeted-jobs-scams-too-0"},
  {id:17,cat:"Scams",icon:"GR",title:"The government selected you for a personal grant",note:"Check unsolicited offers of free money",verdict:"Potentially misleading",level:"Beginner",time:10,image:"https://images.unsplash.com/photo-1526304640581-d334cdbbf45e"+IMG,publisher:"Social media direct message",published:"Grant scam",deck:"A message says a government agency selected you for free money and requests a fee and bank details.",body:["Real government grants require applications for specific purposes.","Agencies do not contact people out of the blue to offer personal grant money.","The request for an upfront fee and financial information are strong scam signals."],prompt:"Where is the authoritative directory for legitimate federal grants?",hint:"Go directly to Grants.gov rather than the link sent in the message.",source:"https://consumer.ftc.gov/articles/government-grant-scams"},
  {id:18,cat:"Technology",icon:"VC",title:"Your executive team appears on an urgent video call",note:"Defend against multi-person deepfake impersonation",verdict:"Potentially misleading",level:"Advanced",time:15,image:"https://images.unsplash.com/photo-1516321318423-f06f85e504b3"+IMG,publisher:"Unexpected video meeting",published:"Deepfake scam",deck:"A finance employee joins a video meeting where familiar executives urgently request a confidential transfer.",body:["Faces and voices can now be synthesized from public recordings.","Urgency, secrecy, and bypassing normal approval are stronger clues than visual quality alone.","A separate known channel should verify any high-risk request."],prompt:"What out-of-band check would break the attack?",hint:"Call a known number and follow the normal multi-person approval process.",source:"https://www.cyber.gov.au/publication/personal-cyber-security-handbook/learn-how-to-spot-scams"},
  {id:19,cat:"Scams",icon:"PR",title:"You won a prize—but must pay first",note:"Identify fee-before-reward fraud",verdict:"Potentially misleading",level:"Beginner",time:10,image:"https://images.unsplash.com/photo-1492684223066-81342ee5ff30"+IMG,publisher:"Prize notification",published:"Prize scam",deck:"A message says you won a contest you do not remember entering and must pay tax or shipping to receive it.",body:["The sender asks for money or banking details before releasing the supposed prize.","The contest rules, sponsor identity, and entry record cannot be verified.","Legitimate prizes do not require winners to pay to receive winnings."],prompt:"Did you enter, and can the sponsor confirm the award independently?",hint:"Never pay for a prize; locate the sponsor through its official site.",source:"https://consumer.ftc.gov/features/pass-it-on/youve-won-scams"},
  {id:20,cat:"Climate",icon:"WX",title:"One viral chart proves climate change is a hoax",note:"Inspect axes, time ranges, and missing context",verdict:"Insufficient evidence",level:"Advanced",time:15,image:"https://images.unsplash.com/photo-1500530855697-b586d89ba3ee"+IMG,publisher:"Screenshot without dataset",published:"Data literacy case",deck:"A cropped chart shows a short temperature period and claims it disproves long-term climate change.",body:["The chart omits the dataset link, geographic coverage, and a long-term baseline.","A short selected period can hide the broader trend.","A defensible conclusion requires the original data and transparent methods."],prompt:"What changes when you expand the time scale and inspect the original dataset?",hint:"Find the chart's original source, then check axes, baseline, location, and full date range.",source:"https://www.ncei.noaa.gov/news/weather-vs-climate"},
  {id:21,cat:"Campus",icon:"MIT",truth:"Verified real",title:"MIT expands tuition-free aid below $200,000",note:"Verify a surprising campus announcement through primary sources",verdict:"Likely credible",level:"Beginner",time:11,publisher:"MIT News",published:"Official announcement · 2024",deck:"A post says MIT undergraduates from families earning under $200,000 can typically attend tuition-free beginning in fall 2025.",body:["The claim links to a named university announcement rather than an anonymous screenshot.","MIT Student Financial Services publishes the same income threshold and explains typical-assets conditions.","Independent coverage can confirm the announcement, but the university policy page is the strongest source."],prompt:"Which details and conditions must be preserved when sharing the headline?",hint:"Check the effective academic year, undergraduate scope, and the phrase ‘with typical assets.’",source:"https://news.mit.edu/2024/mit-tuition-undergraduates-family-income-1120"},
  {id:22,cat:"Campus",icon:"PX",truth:"AI-generated fake",title:"A synthetic campus protest photo goes viral",note:"Separate an emotional AI image from a documented event",verdict:"Potentially misleading",level:"Intermediate",time:13,publisher:"Unverified social account",published:"AI image training case",deck:"A dramatic image claims to show hundreds of students surrounding a university building after an emergency policy decision.",body:["The image has no photographer, original file, date, or local report.","Signs and faces contain inconsistent details, but visual artefacts alone are not decisive.","Verification requires campus alerts, local reporting, reverse search, and the earliest upload."],prompt:"What evidence outside the image should exist if the event happened?",hint:"Look for campus safety notices, student newspaper coverage, and independent photos from the same location.",source:"https://fullfact.org/blog/2025/apr/spotting-AI-content-guide/"},
  {id:23,cat:"Health & Science",icon:"CR",truth:"Verified real",title:"The FDA approved the first CRISPR-based therapy",note:"Confirm a medical breakthrough without exaggerating it",verdict:"Likely credible",level:"Intermediate",time:14,publisher:"U.S. Food and Drug Administration",published:"Regulatory announcement · 2023",deck:"A headline says the FDA approved the first treatment using CRISPR/Cas9 genome editing for sickle cell disease.",body:["The FDA names the therapy, indication, eligible age group, manufacturer, and approval date.","The announcement describes a specific treatment—not a universal cure for every genetic disease.","The approval letter and scientific review provide stronger evidence than a promotional summary."],prompt:"Which limitations keep the headline accurate?",hint:"Identify the disease, patient group, treatment name, and what ‘first’ refers to.",source:"https://www.fda.gov/news-events/press-announcements/fda-approves-first-gene-therapies-treat-patients-sickle-cell-disease"},
  {id:24,cat:"Health & Science",icon:"DR",truth:"AI-generated fake",title:"A famous doctor endorses a miracle supplement",note:"Detect a synthetic endorsement wrapped around health claims",verdict:"Potentially misleading",level:"Advanced",time:14,publisher:"Sponsored social video",published:"Synthetic endorsement case",deck:"A polished video appears to show a well-known doctor promising that one supplement reverses a chronic condition in days.",body:["The clip links to a sales page but not a clinical study, regulator, or full interview.","Voice and lip movement can be cloned, while titles and logos can be copied.","Medical efficacy requires inspectable evidence even if the speaker were genuine."],prompt:"How would you verify both the person and the treatment claim?",hint:"Check the person's official channels, then search the regulator and clinical literature separately.",source:"https://consumer.ftc.gov/consumer-alerts/2023/03/scammers-use-ai-enhance-their-family-emergency-schemes"},
  {id:25,cat:"Technology",icon:"DT",truth:"Verified real",title:"NASA deliberately changed an asteroid's orbit",note:"Trace a spectacular science claim to measurements",verdict:"Likely credible",level:"Intermediate",time:13,publisher:"NASA",published:"Mission result · 2022",deck:"NASA says its DART spacecraft changed the orbital period of the asteroid moonlet Dimorphos after a deliberate impact.",body:["NASA published the mission design, observation method, measured period change, and uncertainty.","Multiple telescopes measured the orbit before and after impact.","The result demonstrates a deflection technique; it does not mean a dangerous asteroid was heading toward Earth."],prompt:"What measurement turns the claim from spectacle into evidence?",hint:"Compare the orbital period before and after impact and note the uncertainty.",source:"https://www.nasa.gov/news-release/nasa-confirms-dart-mission-impact-changed-asteroids-motion-in-space/"},
  {id:26,cat:"Technology",icon:"FP",truth:"Verified real",title:"An AI detector can flag a real image by mistake",note:"Learn why detector scores are clues, not verdicts",verdict:"Likely credible",level:"Advanced",time:15,publisher:"Full Fact investigation",published:"Detection-tool investigation · 2026",deck:"A fact-checking investigation found apparently genuine political photos that an AI watermark detector initially described as AI-made or edited.",body:["The investigation contacted the people who published the images and tested professional detection tools.","The detector provider changed some results to ‘Unsure’ after reviewing the findings.","A detection score must be combined with provenance, source contact, reverse search, and context."],prompt:"Why is a detector result insufficient as a final ruling?",hint:"Look for false positives, model limits, and evidence independent of the detector.",source:"https://fullfact.org/toolkit/google-synthid-detector-flagging-apparently-real-images/"},
  {id:27,cat:"Public Policy",icon:"EU",truth:"Verified real",title:"The European Union's AI Act entered into force",note:"Verify a policy headline and its implementation timeline",verdict:"Likely credible",level:"Intermediate",time:13,publisher:"European Commission",published:"Official policy update · 2024",deck:"A policy post says the EU AI Act entered into force on 1 August 2024 and applies requirements according to risk.",body:["The European Commission and Council publish matching dates and legal context.","Entry into force does not mean every obligation applied immediately on that day.","A responsible summary distinguishes adoption, entry into force, and phased application."],prompt:"Which date and legal stage does the headline describe?",hint:"Open the official implementation timeline and separate entry into force from later compliance dates.",source:"https://commission.europa.eu/news-and-media/news/ai-act-enters-force-2024-08-01_en"},
  {id:28,cat:"Public Policy",icon:"EL",truth:"AI-generated fake",title:"AI images manufacture political support that never happened",note:"Check whether a campaign photo documents a real event",verdict:"Potentially misleading",level:"Advanced",time:14,publisher:"Coordinated social posts",published:"Election misinformation · 2024",deck:"Photorealistic images claim to show a political candidate surrounded by supporters at events that cannot be traced.",body:["Creators acknowledged that some images were generated with AI.","The posts offered no event date, venue, photographer, or matching footage.","Synthetic political images can influence perception even when the underlying scene never occurred."],prompt:"How can you verify whether the depicted gathering existed?",hint:"Search event schedules, local reports, reverse-image results, and creator disclosures.",source:"https://apnews.com/article/72194f59823037391b3888a1720ba7c2"},
  {id:29,cat:"Image Verification",icon:"MG",truth:"AI-generated fake",title:"Did Katy Perry attend the Met Gala in this dress?",note:"Use event records and scene details to expose a synthetic celebrity photo",verdict:"Potentially misleading",level:"Intermediate",time:12,publisher:"Viral fan posts",published:"AI image case · 2024",deck:"Images appear to show Katy Perry posing on the Met Gala carpet even though she did not attend the event.",body:["The carpet design in one image matches an earlier year rather than the current event.","Official attendee coverage and the celebrity's own post contradict the claim.","A convincing backdrop can be assembled from training images of past events."],prompt:"Which event-specific detail gives the quickest contradiction?",hint:"Compare the carpet, official arrivals gallery, and the subject's verified account.",source:"https://apnews.com/article/3b3d2da6c57c0b0b563149c32851297f"},
  {id:30,cat:"Image Verification",icon:"AR",truth:"AI-generated fake",title:"Is this Earth photo from the Artemis II mission?",note:"Compare a viral space image with the official mission archive",verdict:"Potentially misleading",level:"Advanced",time:14,publisher:"Unverified image account",published:"AI image case · 2026",deck:"A cinematic image of Earth is shared as a photograph taken during NASA's Artemis II mission.",body:["The post provides no NASA image identifier, timestamp, camera, or mission archive link.","NASA directed fact-checkers to its official image feed, where the viral picture does not appear.","Several visual patterns and provenance checks indicate the image was almost certainly AI-generated."],prompt:"What would a genuine mission image normally include?",hint:"Look for an agency asset page, credit line, capture date, and mission metadata.",source:"https://fullfact.org/technology/artemis-2-earth-pictures-fake-ai/"},
  {id:31,cat:"Scams",icon:"FM",truth:"AI-generated fake",title:"A family member's cloned voice asks for emergency money",note:"Break a voice-cloning scam with an independent callback",verdict:"Potentially misleading",level:"Intermediate",time:12,publisher:"Unexpected phone call",published:"AI voice scam",deck:"A panicked caller sounds exactly like a relative and says money must be sent immediately after an accident.",body:["A short public audio clip can provide enough material for voice cloning.","Urgency and hard-to-reverse payment methods are stronger signals than familiarity of the voice.","The safest check is to call the relative using a number you already know."],prompt:"What verification step works even if the cloned voice is perfect?",hint:"End the call and contact the person or another family member through a known channel.",source:"https://consumer.ftc.gov/consumer-alerts/2023/03/scammers-use-ai-enhance-their-family-emergency-schemes"},
  {id:32,cat:"Scams",icon:"IV",truth:"AI-generated fake",title:"A celebrity deepfake promises guaranteed trading profits",note:"Verify the promoter and the financial firm separately",verdict:"Potentially misleading",level:"Advanced",time:15,publisher:"Paid social advertisement",published:"Investment scam",deck:"A realistic video appears to show a celebrity recommending a trading platform with guaranteed returns.",body:["Scam advertisements can combine cloned video with a professional-looking but unauthorized website.","Guaranteed profit and pressure to deposit quickly conflict with legitimate risk disclosures.","A regulator's register and warning list matter more than the face in the advertisement."],prompt:"Which two identities must be verified before investing?",hint:"Check both the speaker's official channel and the firm's regulatory authorization.",source:"https://www.fca.org.uk/consumers/online-trading-scams"},
  {id:33,cat:"Climate",icon:"24",truth:"Verified real",title:"2024 was the warmest year in the global record",note:"Read a climate headline with its dataset and uncertainty",verdict:"Likely credible",level:"Intermediate",time:14,publisher:"World Meteorological Organization",published:"Climate assessment · 2025",deck:"The WMO says 2024 was the warmest year in the 175-year observational record, based on six international datasets.",body:["The assessment synthesizes six datasets and reports a margin of uncertainty.","The global annual average is not the same as every location being hottest every day.","One year above 1.5°C does not by itself mean the Paris Agreement's long-term threshold has been permanently crossed."],prompt:"Which caveat prevents a correct headline from becoming misleading?",hint:"Distinguish one calendar year from a multi-decade warming level.",source:"https://wmo.int/news/media-centre/wmo-confirms-2024-warmest-year-record-about-155degc-above-pre-industrial-level"},
  {id:34,cat:"Climate",icon:"LA",truth:"AI-generated fake",title:"Downtown Los Angeles burned in the wildfire",note:"Trace dramatic disaster imagery to an AI-art account",verdict:"Potentially misleading",level:"Intermediate",time:13,publisher:"Viral before-and-after post",published:"AI disaster image · 2025",deck:"A before-and-after image claims that downtown Los Angeles skyscrapers were engulfed by the January 2025 wildfires.",body:["The affected wildfire areas did not include the depicted downtown skyline.","Reverse search leads to a creator who used generative AI and labelled related work as AI art.","Real disaster coverage exists, but genuine tragedy does not authenticate every viral visual."],prompt:"How do location checks and provenance work together here?",hint:"Identify the buildings, compare official fire maps, and trace the earliest upload.",source:"https://factcheck.afp.com/doc.afp.com.36YC4C3"},
  {id:35,cat:"Finance",icon:"₿",truth:"Verified real",title:"The SEC approved spot bitcoin exchange-traded products",note:"Separate regulatory approval from investment endorsement",verdict:"Likely credible",level:"Advanced",time:15,publisher:"U.S. Securities and Exchange Commission",published:"Regulatory statement · 2024",deck:"A finance headline says the SEC approved the listing and trading of several spot bitcoin exchange-traded product shares.",body:["The SEC published the approval and described the legal context.","The statement explicitly says approval does not endorse bitcoin or remove its risks.","A careful summary distinguishes product listing approval from a judgment that the asset is safe."],prompt:"Which phrase would turn a true regulatory event into a misleading investment claim?",hint:"Approval is not the same as endorsement, guarantee, or low risk.",source:"https://www.sec.gov/newsroom/speeches-statements/gensler-statement-spot-bitcoin-011023"},
  {id:36,cat:"Finance",icon:"AI",truth:"AI-generated fake",title:"An AI finance expert guarantees 30% monthly returns",note:"Identify fabricated expertise and impossible certainty",verdict:"Potentially misleading",level:"Intermediate",time:13,publisher:"Unlicensed trading platform",published:"Synthetic investment promotion",deck:"A polished avatar presents market charts and claims an automated system guarantees unusually high monthly returns.",body:["Synthetic presenters and copied news graphics can make an unlicensed firm look established.","No legitimate investment can guarantee high returns without risk.","The platform's authorization and withdrawal record matter more than presentation quality."],prompt:"What should you verify before depositing any money?",hint:"Search the regulator's register, warning list, legal entity, and independent withdrawal complaints.",source:"https://www.fca.org.uk/consumers/online-trading-scams"},
  {id:37,cat:"Social Media",icon:"CC",truth:"Verified real",title:"Content Credentials can record how media was made",note:"Understand provenance without treating it as a truth machine",verdict:"Likely credible",level:"Advanced",time:15,publisher:"Coalition for Content Provenance and Authenticity",published:"Open specification",deck:"A post says Content Credentials can attach tamper-evident provenance information about how a digital asset was created or changed.",body:["The C2PA specification defines signed manifests that can record origin and editing actions.","Valid provenance can show who signed a record and whether it changed.","Content Credentials do not prove that every depicted event or written claim is true."],prompt:"What can provenance establish—and what can it not establish?",hint:"Separate integrity and editing history from the truth of the scene or claim.",source:"https://spec.c2pa.org/specifications/specifications/2.4/specs/ContentCredentials.html"},
  {id:38,cat:"Social Media",icon:"VS",truth:"AI-generated fake",title:"A viral image invents supporters at a political event",note:"Investigate coordinated sharing and missing event evidence",verdict:"Potentially misleading",level:"Advanced",time:14,publisher:"Coordinated social accounts",published:"Synthetic political content",deck:"Multiple accounts share photorealistic images of a candidate with supporters, but no identifiable event can be located.",body:["High engagement and repeated captions do not create independent confirmation.","Some creators acknowledged generating the images with AI tools.","The verification target is the alleged event, not only whether pixels look unusual."],prompt:"How do you avoid counting copied posts as separate evidence?",hint:"Trace posts to their earliest source and look for independent event documentation.",source:"https://apnews.com/article/72194f59823037391b3888a1720ba7c2"}
];

const aiGeneratedIds=new Set([1,2,3,4,5,18,22,24,28,29,30,31,32,34,36,38]);
cases.forEach(c=>{if(!c.truth)c.truth=aiGeneratedIds.has(c.id)?"AI-generated fake":"False or misleading";});

const views=[...document.querySelectorAll("[data-view]")], routeButtons=[...document.querySelectorAll("[data-route]")], navButtons=[...document.querySelectorAll(".bottom-nav [data-route]")];
const toast=document.getElementById("toast");
const defaultState={completed:[],wrongbook:[],stamina:5,streak:1,bestStreak:1,badges:[],recharges:0,sound:true,lastStudy:""};
const badgeDefinitions=[
  {key:"first",icon:"⌕",tone:"blue-badge",title:"First Look",rule:"Complete 1 case"},
  {key:"five",icon:"↗",tone:"mint-badge",title:"Case Closer",rule:"Complete 5 cases"},
  {key:"ten",icon:"10",tone:"gold-badge",title:"Deep Investigator",rule:"Complete 10 cases"},
  {key:"all",icon:"38",tone:"blue-badge",title:"Library Legend",rule:"Complete all 38 cases"},
  {key:"streak3",icon:"3",tone:"mint-badge",title:"Momentum",rule:"Learn 3 days in a row"},
  {key:"streak",icon:"◎",tone:"gold-badge",title:"Seven-Day Streak",rule:"Learn 7 days in a row"},
  {key:"perfect",icon:"◇",tone:"blue-badge",title:"Perfect Evidence",rule:"Score 100 without hints"},
  {key:"comeback",icon:"⚡",tone:"gold-badge",title:"Comeback Learner",rule:"Recharge stamina once"},
  {key:"reviewer",icon:"↻",tone:"mint-badge",title:"Review Ready",rule:"Save 3 questions for review"},
  {key:"image",icon:"▧",tone:"blue-badge",title:"Image Tracer",rule:"Complete 3 image cases"},
  {key:"scam",icon:"$",tone:"gold-badge",title:"Scam Spotter",rule:"Complete 3 scam cases"},
  {key:"variety",icon:"✦",tone:"mint-badge",title:"Method Mixer",rule:"Complete cases in 4 categories"}
];
let state={...defaultState,...JSON.parse(localStorage.getItem("factpeekGame")||"{}")};
let activeFilter="All",activeTruth="All", currentCase=cases[0], questionIndex=0, score=100, correctCount=0, hintsUsed=0, selected=[], order=[], startedAt=Date.now(), pendingCorrect=false;

function caseImage(c){const palettes=[["#1f64e0","#8bb8ff"],["#0d7764","#8fe2c9"],["#d95048","#ffaca5"],["#8a5e08","#ffd476"],["#533aa8","#b7a8ff"]],p=palettes[(c.id-1)%palettes.length],shapes=Array.from({length:6},(_,i)=>`<circle cx="${80+i*145}" cy="${55+(i%3)*110}" r="${36+i*7}" fill="white" opacity="${.06+i*.025}"/>`).join("");return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 420"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${p[0]}"/><stop offset="1" stop-color="${p[1]}"/></linearGradient></defs><rect width="900" height="420" fill="url(#g)"/>${shapes}<path d="M0 340 C170 240 330 440 510 320 S760 250 900 330 V420 H0Z" fill="#102c2b" opacity=".2"/><text x="64" y="285" fill="white" font-family="Arial,sans-serif" font-size="150" font-weight="800">${c.icon}</text></svg>`)}`;}

function save(){localStorage.setItem("factpeekGame",JSON.stringify(state));updateProfile();}
function showToast(message){toast.textContent=message;toast.classList.add("is-visible");clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove("is-visible"),2600);}
function navigate(route){const target=document.querySelector(`[data-view="${route}"]`);if(!target)return;views.forEach(v=>v.classList.toggle("is-active",v===target));navButtons.forEach(b=>b.classList.toggle("is-active",b.dataset.route===route));document.body.classList.toggle("login-active",route==="login");window.scrollTo({top:0,behavior:"smooth"});history.replaceState(null,"",`#${route}`);if(route==="profile")updateProfile();if(route==="case"){const t=document.getElementById("caseTruth");t.textContent=currentCase.truth.toUpperCase();t.style.background=currentCase.truth==="Verified real"?"rgba(227,246,239,.94)":currentCase.truth.startsWith("AI")?"rgba(255,240,237,.94)":"rgba(255,241,212,.94)";}}
routeButtons.forEach(b=>b.addEventListener("click",()=>navigate(b.dataset.route)));

function playTone(kind){if(!state.sound)return;const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const ctx=new C(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=kind==="good"?660:kind==="win"?520:180;o.type=kind==="bad"?"sawtooth":"sine";g.gain.setValueAtTime(.08,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.28);o.start();o.stop(ctx.currentTime+.3);if(kind==="win")setTimeout(()=>playTone("good"),140);}
document.getElementById("soundToggle").addEventListener("click",e=>{state.sound=!state.sound;e.currentTarget.classList.toggle("sound-on",state.sound);e.currentTarget.textContent=state.sound?"♪":"×";save();showToast(state.sound?"Game sounds on":"Game sounds off");});

function renderCases(){const q=document.getElementById("caseSearch").value.trim().toLowerCase();const done=new Set(state.completed);const result=cases.filter(c=>(activeFilter==="All"||c.cat===activeFilter)&&(activeTruth==="All"||c.truth===activeTruth)&&`${c.title} ${c.cat} ${c.note} ${c.truth}`.toLowerCase().includes(q));document.getElementById("caseGrid").innerHTML=result.map(c=>`<article class="library-card" tabindex="0" role="button" aria-label="Open case: ${c.title}" data-case-id="${c.id}"><div class="card-art" style="background-image:linear-gradient(180deg,transparent,rgba(8,28,27,.58)),url('${caseImage(c)}')"><span>${c.cat}</span><b>${c.icon}</b></div><div class="card-content"><div class="case-status">${done.has(c.id)?"✓ COMPLETED":"CASE "+String(c.id).padStart(2,"0")}</div><span class="truth-tag ${c.truth.startsWith("AI")?"ai":c.truth.startsWith("False")?"false":""}">${c.truth}</span><h2>${c.title}</h2><p>${c.note}</p><div class="card-footer"><span>${c.level} · ${c.time} min</span><span class="tag ${c.verdict.includes("misleading")?"tag-coral":""}">${c.verdict}</span></div></div></article>`).join("");document.getElementById("emptyState").hidden=result.length>0;document.querySelectorAll(".library-card").forEach(card=>{const open=()=>openCase(Number(card.dataset.caseId));card.onclick=open;card.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();open();}};});}
document.getElementById("caseSearch").addEventListener("input",renderCases);document.querySelectorAll(".filter-chip").forEach(b=>b.addEventListener("click",()=>{activeFilter=b.dataset.filter;document.querySelectorAll(".filter-chip").forEach(x=>x.classList.toggle("is-selected",x===b));renderCases();}));
document.querySelectorAll(".truth-chip").forEach(b=>b.addEventListener("click",()=>{activeTruth=b.dataset.truth;document.querySelectorAll(".truth-chip").forEach(x=>x.classList.toggle("is-selected",x===b));renderCases();}));

function openCase(id){currentCase=cases.find(c=>c.id===id)||cases[0];questionIndex=0;score=100;correctCount=0;hintsUsed=0;startedAt=Date.now();document.getElementById("caseCover").style.backgroundImage=`linear-gradient(180deg,transparent,rgba(8,28,27,.52)),url('${caseImage(currentCase)}')`;document.getElementById("caseType").textContent=currentCase.cat.toUpperCase();document.getElementById("caseMeta").innerHTML=`<span>CASE ${String(currentCase.id).padStart(2,"0")}</span><span>${currentCase.cat} · ${currentCase.level}</span><span>${currentCase.time} min</span>`;document.getElementById("caseTitle").textContent=currentCase.title;document.getElementById("caseDeck").textContent=currentCase.deck;document.getElementById("caseAvatar").textContent=currentCase.icon;document.getElementById("casePublisher").textContent=currentCase.publisher;document.getElementById("casePublished").textContent=currentCase.published;document.getElementById("articleBody").innerHTML=currentCase.body.map((p,i)=>`<p data-clue="${i}">${p}</p>`).join("")+`<p class="reader-task">Click sentences that deserve verification. Mark at least one clue before you finish.</p>`;document.getElementById("casePrompt").textContent=currentCase.prompt;const a=document.getElementById("caseSource");a.href=currentCase.source;a.textContent="Open the reference source ↗";document.querySelectorAll("#articleBody [data-clue]").forEach(p=>p.onclick=()=>{p.classList.toggle("is-highlighted");showToast(p.classList.contains("is-highlighted")?"Clue marked +2 focus":"Clue unmarked");});navigate("case");renderQuestion();}

function getQuestion(){const base=[{type:"single",label:"Evidence judgment",q:"Based on the evidence available, how should this claim be labeled?",options:["Likely credible","Potentially misleading","Insufficient evidence"],answer:currentCase.verdict,explain:`The defensible label is “${currentCase.verdict}.” A conclusion should match the strength of available evidence.`},{type:currentCase.id%3===0?"boolean":currentCase.id%3===1?"multi":"text",label:"Signal check",q:currentCase.id%3===0?"True or false: a familiar voice, logo, or account name proves the message is authentic.":currentCase.id%3===1?"Which two signals should make you pause?":"Write one concrete action you would take before sharing this claim.",options:currentCase.id%3===0?["True","False"]:["No traceable primary source","Urgent or absolute language","Multiple independent reports","Transparent methods and data"],answer:currentCase.id%3===0?"False":[0,1],explain:"Identity cues can be copied. Trace the origin, inspect context, and verify independently."},{type:"order",label:"Verification sequence",q:"Put the verification steps in the strongest order.",options:["Find the original source","Check date and full context","Compare independent reliable sources"],answer:[0,1,2],explain:"Start with origin, then context, then independent confirmation."},{type:"single",label:"Best evidence",q:"Which source is strongest for resolving this case?",options:["The official or original record linked in the case","A viral repost with many likes","An anonymous comment agreeing with the claim"],answer:"The official or original record linked in the case",explain:"Authority, proximity to the event, transparency, and independent corroboration matter more than popularity."}];return base[questionIndex];}

function renderQuestion(){const q=getQuestion();selected=[];order=[];document.getElementById("hudProgress").textContent=`Question ${questionIndex+1} of 4`;document.getElementById("hudScore").textContent=`${score} pts`;document.getElementById("hudStamina").textContent=`⚡ ${state.stamina}`;document.getElementById("quizStep").textContent=q.label.toUpperCase();document.getElementById("quizQuestion").textContent=q.q;document.getElementById("quizInstruction").textContent=q.type==="multi"?"Choose two":q.type==="order"?"Tap each item in the correct order":q.type==="text"?"A short response is enough":"Choose one";const box=document.getElementById("quizOptions");if(q.type==="text")box.innerHTML=`<textarea class="short-answer" id="shortAnswer" placeholder="I would…"></textarea>`;else box.innerHTML=q.options.map((x,i)=>`<button data-index="${i}" data-value="${x}"><span>${String.fromCharCode(65+i)}</span><strong>${x}</strong>${q.type==="order"?"<small class='order-number'></small>":""}</button>`).join("");document.getElementById("submitQuiz").disabled=true;document.getElementById("submitQuiz").textContent="Check answer";document.getElementById("hintPanel").hidden=true;document.getElementById("hintButton").disabled=false;if(q.type==="text"){document.getElementById("shortAnswer").oninput=e=>document.getElementById("submitQuiz").disabled=e.target.value.trim().length<12;}else document.querySelectorAll("#quizOptions button").forEach(b=>b.onclick=()=>selectOption(b,q));}
function selectOption(b,q){const i=Number(b.dataset.index);if(q.type==="multi"){b.classList.toggle("is-selected");selected=[...document.querySelectorAll("#quizOptions button.is-selected")].map(x=>Number(x.dataset.index));document.getElementById("submitQuiz").disabled=selected.length!==2;}else if(q.type==="order"){if(order.includes(i))return;order.push(i);b.classList.add("is-selected");b.querySelector(".order-number").textContent=order.length;document.getElementById("submitQuiz").disabled=order.length!==q.options.length;}else{selected=[b.dataset.value];document.querySelectorAll("#quizOptions button").forEach(x=>x.classList.toggle("is-selected",x===b));document.getElementById("submitQuiz").disabled=false;}}

document.getElementById("hintButton").onclick=()=>{if(!document.getElementById("hintPanel").hidden)return;hintsUsed++;score=Math.max(0,score-5);document.getElementById("hudScore").textContent=`${score} pts`;document.getElementById("hintPanel").textContent=currentCase.hint;document.getElementById("hintPanel").hidden=false;document.getElementById("hintButton").disabled=true;playTone("good");};
document.getElementById("submitQuiz").onclick=()=>{const q=getQuestion();let correct;if(q.type==="text")correct=document.getElementById("shortAnswer").value.trim().length>=12;else if(q.type==="multi")correct=JSON.stringify([...selected].sort())===JSON.stringify([...q.answer].sort());else if(q.type==="order")correct=JSON.stringify(order)===JSON.stringify(q.answer);else correct=selected[0]===q.answer;pendingCorrect=correct;if(correct){correctCount++;playTone("good");showResult(true,"Evidence secured!",q.explain);}else{score=Math.max(0,score-15);state.stamina=Math.max(0,state.stamina-1);state.wrongbook.unshift({caseId:currentCase.id,title:currentCase.title,question:q.q,date:new Date().toLocaleDateString()});state.wrongbook=state.wrongbook.slice(0,30);save();playTone("bad");showResult(false,"Not quite—follow the evidence",q.explain);document.getElementById("mascot").classList.add("shake");setTimeout(()=>document.getElementById("mascot").classList.remove("shake"),500);}};
function showResult(good,title,text){const o=document.getElementById("resultOverlay");document.getElementById("resultIcon").textContent=good?"✓":"×";document.getElementById("resultIcon").className="result-icon "+(good?"good":"bad");document.getElementById("resultTitle").textContent=title;document.getElementById("resultText").textContent=text;o.hidden=false;}
document.getElementById("continueQuiz").onclick=()=>{document.getElementById("resultOverlay").hidden=true;if(!pendingCorrect&&state.stamina<=0){document.getElementById("staminaOverlay").hidden=false;return;}questionIndex++;if(questionIndex>=4)finishCase();else renderQuestion();};
document.getElementById("goLearnButton").onclick=()=>{document.getElementById("staminaOverlay").hidden=true;navigate("learn");};

function finishCase(){const elapsed=Math.max(1,Math.round((Date.now()-startedAt)/1000)),accuracy=Math.round(correctCount/4*100);if(!state.completed.includes(currentCase.id))state.completed.push(currentCase.id);const today=new Date().toDateString();if(state.lastStudy!==today){state.streak=state.lastStudy?Math.max(1,state.streak+1):1;state.bestStreak=Math.max(state.bestStreak,state.streak);state.lastStudy=today;}unlockBadges(accuracy);save();document.getElementById("summaryTitle").textContent=accuracy>=75?"Evidence secured.":"Case reviewed. Skills growing.";document.getElementById("summaryMessage").textContent=`You completed “${currentCase.title}”. ${state.wrongbook.filter(x=>x.caseId===currentCase.id).length} answer(s) are ready for review in your wrong-answer book.`;document.getElementById("summaryTime").textContent=`${String(Math.floor(elapsed/60)).padStart(2,"0")}:${String(elapsed%60).padStart(2,"0")}`;document.getElementById("summaryAccuracy").textContent=`${accuracy}%`;document.getElementById("summaryScore").textContent=score;document.getElementById("summaryHints").textContent=hintsUsed;document.getElementById("summaryStreak").textContent=`${state.streak} day streak`;navigate("summary");confetti();playTone("win");}
function unlockBadges(accuracy){if(accuracy===100&&hintsUsed===0&&!state.badges.includes("perfect"))state.badges.push("perfect");syncAchievementBadges();}
function syncAchievementBadges(){const add=k=>{if(!state.badges.includes(k))state.badges.push(k);},done=state.completed.map(id=>cases.find(c=>c.id===id)).filter(Boolean),cats=new Set(done.map(c=>c.cat));if(done.length>=1)add("first");if(done.length>=5)add("five");if(done.length>=10)add("ten");if(done.length>=38)add("all");if(state.streak>=3)add("streak3");if(state.streak>=7)add("streak");if(state.recharges>=1)add("comeback");if(state.wrongbook.length>=3)add("reviewer");if(done.filter(c=>c.cat==="Image Verification").length>=3)add("image");if(done.filter(c=>c.cat==="Scams").length>=3)add("scam");if(cats.size>=4)add("variety");}
function badgeProgress(key){const done=state.completed.map(id=>cases.find(c=>c.id===id)).filter(Boolean),cats=new Set(done.map(c=>c.cat)),values={first:`${Math.min(done.length,1)} / 1`,five:`${Math.min(done.length,5)} / 5`,ten:`${Math.min(done.length,10)} / 10`,all:`${Math.min(done.length,38)} / 38`,streak3:`${Math.min(state.streak,3)} / 3 days`,streak:`${Math.min(state.streak,7)} / 7 days`,perfect:state.badges.includes("perfect")?"Completed":"Best score needed",comeback:`${Math.min(state.recharges,1)} / 1`,reviewer:`${Math.min(state.wrongbook.length,3)} / 3`,image:`${Math.min(done.filter(c=>c.cat==="Image Verification").length,3)} / 3`,scam:`${Math.min(done.filter(c=>c.cat==="Scams").length,3)} / 3`,variety:`${Math.min(cats.size,4)} / 4 categories`};return values[key];}
function renderBadgeVault(){syncAchievementBadges();document.getElementById("allBadgeGrid").innerHTML=badgeDefinitions.map(b=>`<article class="${state.badges.includes(b.key)?"":"is-locked"}"><div class="badge-shape ${b.tone}">${b.icon}</div><h3>${b.title}</h3><p>${b.rule}</p><small>${state.badges.includes(b.key)?"UNLOCKED":badgeProgress(b.key)}</small></article>`).join("");}
function confetti(){const l=document.getElementById("confettiLayer");l.innerHTML="";for(let i=0;i<55;i++){const s=document.createElement("i");s.style.cssText=`left:${Math.random()*100}%;--d:${1.4+Math.random()*1.8}s;--x:${-70+Math.random()*140}px;background:${["#3176ee","#79d7bd","#ff796f","#efb342"][i%4]}`;l.appendChild(s);}setTimeout(()=>l.innerHTML="",3500);}
document.getElementById("nextCaseButton").onclick=()=>openCase(cases[(cases.indexOf(currentCase)+1)%cases.length].id);

document.getElementById("rechargeButton").onclick=()=>{state.stamina=Math.min(5,state.stamina+3);state.recharges=(state.recharges||0)+1;syncAchievementBadges();save();document.getElementById("learnBattery").style.width="100%";playTone("win");showToast("Stamina recharged +3 ⚡");setTimeout(()=>{navigate("case");renderQuestion();},700);};
function updateProfile(){syncAchievementBadges();document.getElementById("profileCompleted").textContent=state.completed.length;document.getElementById("profileStreak").textContent=`${state.streak} day${state.streak===1?"":"s"}`;document.getElementById("profileBest").textContent=`Best: ${state.bestStreak} day${state.bestStreak===1?"":"s"}`;document.getElementById("profileWrong").textContent=state.wrongbook.length;document.querySelectorAll("[data-badge]").forEach(x=>x.classList.toggle("locked",!state.badges.includes(x.dataset.badge)));const list=document.getElementById("wrongbookList");list.innerHTML=state.wrongbook.length?state.wrongbook.map((x,i)=>`<article><div><span>CASE ${String(x.caseId).padStart(2,"0")}</span><h3>${x.title}</h3><p>${x.question}</p></div><button data-review="${x.caseId}" data-wrong="${i}">Review</button></article>`).join(""):`<div class="empty-wrongbook">No mistakes saved yet. Your review queue is clear.</div>`;document.querySelectorAll("[data-review]").forEach(b=>b.onclick=()=>openCase(Number(b.dataset.review)));}
document.getElementById("clearMastered").onclick=()=>{state.wrongbook=[];save();showToast("Review queue cleared");};
document.getElementById("badgeViewAll").onclick=()=>{renderBadgeVault();document.getElementById("badgeOverlay").hidden=false;document.getElementById("closeBadgeVault").focus();};
document.getElementById("closeBadgeVault").onclick=()=>{document.getElementById("badgeOverlay").hidden=true;document.getElementById("badgeViewAll").focus();};
document.getElementById("badgeOverlay").onclick=e=>{if(e.target===e.currentTarget)document.getElementById("closeBadgeVault").click();};
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!document.getElementById("badgeOverlay").hidden)document.getElementById("closeBadgeVault").click();});

document.getElementById("startChallenge").onclick=()=>openCase(cases.find(c=>!state.completed.includes(c.id))?.id||1);document.getElementById("openDailyCase").onclick=()=>openCase(1);document.getElementById("globalSearch").onkeydown=e=>{if(e.key==="Enter"){document.getElementById("caseSearch").value=e.currentTarget.value;navigate("library");renderCases();}};
const analysisInput=document.getElementById("analysisInput");analysisInput.oninput=()=>{if(analysisInput.value.length>2000)analysisInput.value=analysisInput.value.slice(0,2000);document.getElementById("charCount").textContent=`${analysisInput.value.length} / 2000`;};document.getElementById("uploadDemo").onclick=()=>showToast("Screenshot safety checks will be connected in the full service.");document.getElementById("runAnalysis").onclick=()=>{if(!analysisInput.value.trim()){showToast("Paste story text or a link first");return;}const p=document.getElementById("analysisPanel");p.innerHTML=`<div class="analysis-empty"><div class="radar"><i></i><i></i><span></span></div><h2>Breaking the story into key claims</h2><p>Checking sources, dates, language, and verifiable evidence…</p></div>`;setTimeout(()=>p.innerHTML=`<div class="analysis-result"><div class="analysis-head"><div><p>FIXED EDUCATIONAL DEMO</p><h2>Preliminary analysis</h2></div><span class="verdict">Insufficient evidence</span></div><div class="confidence"><span>Evidence strength</span><div><i></i></div><b>72</b></div><div class="reason-grid"><article><strong>Source</strong><p>No directly verifiable original publisher was found.</p></article><article><strong>Language</strong><p>Absolute language needs a scope check.</p></article><article><strong>Evidence</strong><p>Independent reporting or inspectable data are missing.</p></article></div><p class="analysis-warning">Fixed prototype demo—not a real fact-check. Continue with primary sources and cross-checking.</p></div>`,900);};
document.getElementById("themeToggle").onclick=()=>{document.body.classList.toggle("dark");showToast(document.body.classList.contains("dark")?"Dark mode on":"Light mode on");};document.getElementById("loginForm").onsubmit=e=>{e.preventDefault();navigate("home");showToast("Welcome to FactPeek");};document.getElementById("forgotPassword").onclick=()=>showToast("Password recovery will be connected in the next build.");document.getElementById("createAccount").onclick=()=>showToast("Account creation will be connected in the next build.");

